// modules/vesta.js — Vesta (Fund Analysis + Seguimiento de cartera).
// Extraído de index.html para no seguir creciendo un único archivo de
// ~20k líneas. Cargado desde index.html vía
// <script type="text/babel" src="modules/vesta.js"></script>, en el mismo
// <script type="text/babel"> global que el resto de TrackHub — sin build
// step, así que top-level const/function siguen siendo visibles para el
// resto de la app exactamente igual que antes (los script tags clásicos
// comparten el mismo scope léxico de nivel superior en el navegador).
// No cambia ninguna lógica, es un corte literal del bloque que ya estaba
// aquí.

    // ─── Vesta module ─────────────────────────────────────────────────────────
    const VS_A = "#a78bfa"; // violet
    const VS_B = "#22d3ee"; // cyan

    const VS_CAT_COLOR = {
      equity: "#60a5fa", bonds: "#34d399", commodities: "#f59e0b",
      cash: "#7a90a8", volatility: "#f87171", alternative: "#60a5fa", currency: "#7a90a8",
    };
    const VS_CATEGORIES = ["equity", "bonds", "commodities", "cash", "volatility", "alternative", "currency"];


    // ── Persistencia (Supabase) ──────────────────────────────────────────────
    // Las tres funciones vsLoad* de abajo propagan el error de Supabase en
    // vez de tragárselo. Antes, un fallo transitorio de red/sesión hacía
    // que `data` llegara vacío y la función devolviera `{}` como si
    // sencillamente no hubiera nada guardado — indistinguible de "perfil
    // nuevo, sin datos". Eso es peligroso en concreto para vs_factors: el
    // refresco automático del factor de caja (más abajo, en VestaApp) ve
    // ese `{}` falso, decide que falta el factor de caja, y hace un
    // upsert que REEMPLAZA toda la fila — no la fusiona. Si la carga
    // había fallado en vez de estar realmente vacía, ese upsert borra de
    // un plumazo cualquier índice que hubiera antes. Lanzar el error aquí
    // permite que quien llama decida no guardar nada cuando la carga no
    // se puede confiar (ver el catch en el useEffect de VestaApp).
    const vsLoadFactors = async (profileId) => {
      if (!profileId) return {};
      const { data, error } = await _sb.from("vs_factors").select("data").eq("user_id", _sbUser.id).eq("profile_id", profileId).maybeSingle();
      if (error) throw error;
      return (data && data.data) ? data.data : {};
    };
    const vsSaveFactors = async (profileId, factorsObj) => {
      await _sb.from("vs_factors").upsert({ user_id: _sbUser.id, profile_id: profileId, data: factorsObj }, { onConflict: "user_id,profile_id" });
    };

    // ── Análisis guardados (vs_analyses) ─────────────────────────────────────
    // A diferencia de vs_factors (una fila por perfil), aquí cada análisis
    // guardado es su propia fila — puedes guardar tantos como quieras.
    const vsLoadAnalyses = async (profileId) => {
      if (!profileId) return [];
      const { data } = await _sb.from("vs_analyses").select("id, data, created_at").eq("user_id", _sbUser.id).eq("profile_id", profileId).order("created_at", { ascending: false });
      return data || [];
    };
    const vsSaveAnalysis = async (profileId, analysisObj) => {
      const { data } = await _sb.from("vs_analyses").insert({ user_id: _sbUser.id, profile_id: profileId, data: analysisObj }).select("id, data, created_at").single();
      return data;
    };
    const vsDeleteAnalysis = async (id) => {
      await _sb.from("vs_analyses").delete().eq("id", id).eq("user_id", _sbUser.id);
    };

    // ── Pool de Fondos (vs_funds) ──────────────────────────────────────────
    // Único pool de fondos, reutilizado tanto en "Analizar Fondo" como en
    // "Correlación" — se añade una vez, se usa en los dos sitios. Distinto
    // del pool de Índices (vs_factors), que existe para RBSA.
    const vsLoadFunds = async (profileId) => {
      if (!profileId) return {};
      const { data, error } = await _sb.from("vs_funds").select("data").eq("user_id", _sbUser.id).eq("profile_id", profileId).maybeSingle();
      if (error) throw error;
      return (data && data.data) ? data.data : {};
    };
    const vsSaveFunds = async (profileId, fundsObj) => {
      await _sb.from("vs_funds").upsert({ user_id: _sbUser.id, profile_id: profileId, data: fundsObj }, { onConflict: "user_id,profile_id" });
    };

    // ── Cartera (vs_portfolio) ────────────────────────────────────────────
    // Mismo patrón que vs_funds: una fila JSON por perfil, con
    // { transactions: [...], securities: { ISIN: {isin,name,currency} } }
    // dentro. `securities` es el catálogo de valores ya registrados —
    // permite reutilizar nombre/ISIN/divisa al añadir una compra/venta
    // manual sin volver a escribirlos, y mantiene un nombre consistente
    // para todas las transacciones de un mismo ISIN. Fase 0 = solo modelo
    // de datos + importación; el motor de cálculo (TTWROR/XIRR) llega en
    // la fase siguiente, sobre esta misma tabla.
    const vsLoadPortfolio = async (profileId) => {
      if (!profileId) return { transactions: [], securities: {}, tags: [] };
      const { data, error } = await _sb.from("vs_portfolio").select("data").eq("user_id", _sbUser.id).eq("profile_id", profileId).maybeSingle();
      if (error) throw error;
      const p = (data && data.data) ? data.data : {};
      return { transactions: p.transactions || [], securities: p.securities || {}, tags: p.tags || [] };
    };
    const vsSavePortfolio = async (profileId, portfolioObj) => {
      await _sb.from("vs_portfolio").upsert({ user_id: _sbUser.id, profile_id: profileId, data: portfolioObj }, { onConflict: "user_id,profile_id" });
    };

    // Reconstruye Date objects (incluido startDate) a partir de retornos de
    // fondo persistidos. startDate se guarda desde vsToMonthlyReturns para
    // que la alineación por ventana real siga funcionando aunque el fondo
    // se cargue del pool en vez de subir el CSV cada vez. Si falta (datos
    // guardados antes de este campo, o el primer punto de la serie), se
    // deriva de la fecha del punto anterior — o, si no hay anterior, se
    // retrocede un mes aproximado.
    function vsHydrateFundReturns(storedReturns) {
      const parsed = storedReturns.map(p => ({
        date: new Date(p.date + "T00:00:00Z"),
        value: p.value,
        startDate: p.startDate ? new Date(p.startDate + "T00:00:00Z") : null,
      }));
      for (let i = 0; i < parsed.length; i++) {
        if (!parsed[i].startDate) {
          if (i > 0) {
            parsed[i].startDate = parsed[i-1].date;
          } else {
            const d = new Date(parsed[i].date);
            d.setUTCMonth(d.getUTCMonth() - 1);
            parsed[i].startDate = d;
          }
        }
      }
      return parsed;
    }

    // ── Parsers de CSV ────────────────────────────────────────────────────────
    function vsSplitCSVLine(line){
      const out = []; let cur=''; let inQ=false;
      for(let i=0;i<line.length;i++){
        const c = line[i];
        if(c === '"'){ inQ = !inQ; continue; }
        if(c === ',' && !inQ){ out.push(cur); cur=''; continue; }
        cur += c;
      }
      out.push(cur);
      return out;
    }
    function vsDedupeSeries(series){
      const map = new Map();
      for(const p of series) map.set(p.date.getTime(), p.value);
      return [...map.entries()].map(([t,v])=>({date:new Date(t), value:v})).sort((a,b)=>a.date-b.date);
    }
    // Investing.com usa formatos de fecha distintos según la frecuencia
    // exportada: diario/semanal → "17.08.2026" (DD.MM.YYYY); mensual →
    // "Ago 2026" (mes abreviado + año, sin puntos, en el idioma de la
    // cuenta — cubrimos español e inglés). vsParseInvestingDate reconoce
    // ambos y devuelve un objeto Date en UTC, o null si no reconoce nada.
    const VS_MONTH_MAP = {
      ene:0, feb:1, mar:2, abr:3, may:4, jun:5, jul:6, ago:7, sep:8, oct:9, nov:10, dic:11,
      jan:0, apr:3, aug:7, dec:11, // equivalentes en inglés que difieren del español
    };
    function vsParseInvestingDate(dateStr){
      // Formato diario/semanal: "DD.MM.YYYY"
      if (dateStr.includes('.')) {
        const [d,m,y] = dateStr.split('.');
        if (d && m && y && !isNaN(+d) && !isNaN(+m) && !isNaN(+y)) {
          return new Date(Date.UTC(+y, +m-1, +d));
        }
      }
      // Formato mensual: "Mon YYYY" (ej. "Ago 2026", "Aug 2026")
      const m = dateStr.match(/^([A-Za-zÀ-ÿ]{3})[a-zA-Zà-ÿ]*\s+(\d{4})$/);
      if (m) {
        const monthKey = m[1].toLowerCase();
        const monthIdx = VS_MONTH_MAP[monthKey];
        const year = +m[2];
        if (monthIdx !== undefined && year) {
          // Se ancla al último día del mes, igual que el resto de series
          // mensuales del pipeline (ej. conversión de tipos de interés).
          return new Date(Date.UTC(year, monthIdx + 1, 0));
        }
      }
      return null;
    }

    function vsParseInvestingCSV(text){
      const lines = text.replace(/^\uFEFF/, '').split(/\r?\n/).filter(l => l.trim().length);
      const rows = lines.slice(1);
      const series = [];
      for(const line of rows){
        const cols = vsSplitCSVLine(line);
        if(cols.length < 2) continue;
        const dateStr = cols[0].replace(/"/g,'');
        const valStr = cols[1].replace(/"/g,'');
        const date = vsParseInvestingDate(dateStr);
        if(!date) continue;
        const value = parseFloat(valStr.replace(/\./g,'').replace(',', '.'));
        if(isNaN(value)) continue;
        series.push({date, value});
      }
      series.sort((a,b)=>a.date-b.date);
      return vsDedupeSeries(series);
    }
    function vsParseECBCSV(text){
      const lines = text.replace(/^\uFEFF/, '').split(/\r?\n/).filter(l => l.trim().length);
      const rows = lines.slice(1);
      const series = [];
      for(const line of rows){
        const cols = vsSplitCSVLine(line);
        if(cols.length < 2) continue;
        const dateStr = cols[0].replace(/"/g,'');
        const rateStr = cols[cols.length-1].replace(/"/g,'');
        const date = new Date(dateStr);
        const value = parseFloat(rateStr);
        if(isNaN(date.getTime()) || isNaN(value)) continue;
        series.push({date, value});
      }
      series.sort((a,b)=>a.date-b.date);
      return vsDedupeSeries(series);
    }
    function vsParseFREDCSV(text){
      const lines = text.replace(/^\uFEFF/, '').split(/\r?\n/).filter(l => l.trim().length);
      const rows = lines.slice(1);
      const series = [];
      for(const line of rows){
        const cols = vsSplitCSVLine(line);
        if(cols.length < 2) continue;
        const date = new Date(cols[0].replace(/"/g,''));
        const value = parseFloat(cols[1].replace(/"/g,''));
        if(isNaN(date.getTime()) || isNaN(value)) continue;
        series.push({date, value});
      }
      series.sort((a,b)=>a.date-b.date);
      return vsDedupeSeries(series);
    }

    // ── Conversión a retornos mensuales ─────────────────────────────────────
    function vsMonthKey(date){ return date.getUTCFullYear()*100 + (date.getUTCMonth()+1); }
    function vsToMonthlyReturns(series){
      const byMonth = new Map();
      for(const p of series) byMonth.set(vsMonthKey(p.date), p);
      const monthly = [...byMonth.values()].sort((a,b)=>a.date-b.date);
      const rets = [];
      for(let i=1;i<monthly.length;i++){
        const r = monthly[i].value/monthly[i-1].value - 1;
        // startDate = fecha real de la observación anterior (puede ser de
        // varios meses atrás si hay huecos). Se usa para alinear factores
        // por ventana compuesta en vez de por mes de calendario — ver
        // vsCompoundFactorInWindow.
        rets.push({date: monthly[i].date, startDate: monthly[i-1].date, value:r});
      }
      return rets;
    }
    function vsDaysInMonth(y,m){ return new Date(Date.UTC(y, m, 0)).getUTCDate(); }
    function vsRateToMonthlyReturn(series){
      const groups = new Map();
      for(const p of series){
        const k = vsMonthKey(p.date);
        if(!groups.has(k)) groups.set(k, []);
        groups.get(k).push(p.value);
      }
      const out = [];
      for(const [k, vals] of [...groups.entries()].sort((a,b)=>a[0]-b[0])){
        const y = Math.floor(k/100), m = k%100;
        const avgRate = vals.reduce((a,b)=>a+b,0)/vals.length;
        const dim = vsDaysInMonth(y,m);
        out.push({date: new Date(Date.UTC(y,m,0)), value: (avgRate/100) * (dim/360)});
      }
      return out;
    }

    // ── Factor de caja automático (EONIA + €STR, BCE) ────────────────────────
    // El tipo de interés libre de riesgo en EUR es infraestructura que casi
    // cualquier cesta de RBSA necesita — a diferencia de un índice de
    // mercado (elección discrecional), este no depende de qué fondo estés
    // analizando. La parte reciente (€STR, desde oct-2019) se trae en vivo
    // de la API oficial del BCE y se refresca sola. La parte histórica
    // (EONIA, 1999 → sep-2019) va incrustada aquí como datos fijos — EONIA
    // dejó de publicarse en 2022 y ese tramo ya no cambiará nunca, así que
    // no tiene sentido volver a pedirlo por red cada vez. Empalme hecho
    // cortando EONIA justo donde empieza €STR (1-oct-2019), sin mezclar el
